class Solution {
public:
    int minMaxGame(vector<int>& nums) {
        while (nums.size() > 1) {
            vector<int> nx(nums.size() / 2);
            for (int i = 0; i < nx.size(); i++)
                nx[i] = i % 2 == 0 ? min(nums[2*i], nums[2*i+1]) : max(nums[2*i], nums[2*i+1]);
            nums = nx;
        }
        return nums[0];
    }
};

c.java:
class Solution {
    public int minMaxGame(int[] nums) {
        int n = nums.length;
        while (n > 1) {
            int[] nx = new int[n / 2];
            for (int i = 0; i < n / 2; i++)
                nx[i] = i % 2 == 0 ? Math.min(nums[2*i], nums[2*i+1]) : Math.max(nums[2*i], nums[2*i+1]);
            nums = nx; n /= 2;
        }
        return nums[0];
    }
}

